t-preparation-card-actions"><a class="button button-secondary button-compact" href="/aluno/preparos.php?editar=<?=(int)$row['id']?>" data-student-editor-link>Editar</a><form method="post" data-student-local-form data-local-refresh="preparations-list" data-local-confirm="Excluir esta predefinição? Processamentos que já copiaram estes parâmetros não serão alterados."><input type="hidden" name="_csrf" value="<?=h(csrf_token('student-preparations'))?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$row['id']?>"><button class="button button-danger button-compact" type="submit">Excluir</button></form></div></article><?php endforeach;?></div><?php endif;?></section><?php endif;?>
